{
  "name": "assert_image",
  "category": "ui_assert",
  "group": "ui_assert",
  "subcategory": "visual_verify",
  "doc": "L3 图像断言：优先截取 locator 元素区域；无 locator 时按屏幕 region 裁剪。Android U2/iOS 比对裁剪区域；Harmony 仅 locator 时整屏模板查找，提供 region 时按裁剪区域比对；baseline 不存在时可能自动采集并以 auto_captured=True 返回；SDK 未抛错即通过，无需再断言 auto_captured 或重跑",
  "signature": "(locator=None, baseline_img='', by='text', threshold=0.9, msg='', debug_img='', region=None, allow_auto_capture=True) -> dict",
  "permission": "standard",
  "params": [
    {
      "name": "locator",
      "type": "Locator | None",
      "doc": "元素定位器；与 region 至少提供一个。Android U2/iOS 用于截取区域，Harmony 仅 locator 且无 region 时用于首次基线裁剪/整屏搜图",
      "default": "None"
    },
    {
      "name": "baseline_img",
      "type": "str",
      "doc": "基准图片路径（PNG）；无 locator 自动采集时必须显式提供",
      "default": "''"
    },
    {
      "name": "by",
      "type": "str",
      "doc": "定位方式",
      "default": "'text'"
    },
    {
      "name": "threshold",
      "type": "float",
      "doc": "相似度阈值（0.0~1.0）",
      "default": "0.9"
    },
    {
      "name": "msg",
      "type": "str",
      "doc": "断言失败时的自定义消息",
      "default": "''"
    },
    {
      "name": "debug_img",
      "type": "str",
      "doc": "可选调试图路径；Android U2/iOS 保存元素/区域截图，Harmony OpenCV 回退保存整屏；Android U2 locator 不存在时即使未传也会派生 *_actual_fullscreen 路径保存整屏",
      "default": "''"
    },
    {
      "name": "region",
      "type": "tuple[int,int,int,int] | None",
      "doc": "有 locator 时为元素内相对 ROI (x1,y1,x2,y2)；无 locator 时为屏幕物理坐标（与 assert_ocr 相同，按 window_size 映射）。当前截图与全尺寸历史基线裁同一区域",
      "default": "None"
    },
    {
      "name": "allow_auto_capture",
      "type": "bool",
      "doc": "baseline 缺失时是否允许自动写入；正式门禁建议 False，防止瞬态画面污染黄金样本",
      "default": "True"
    }
  ],
  "returns": {
    "type": "dict",
    "doc": "公共字段为 match、similarity、threshold、baseline_img、auto_captured；auto_captured=True 仅表示本次新建了基线，SDK 未抛错即通过；Android U2/iOS 另含 element_shape、baseline_shape，Harmony 仅 locator 无 region 时不提供这两个 shape 字段；失败抛 AssertionError"
  },
  "usage": "# 场景：验证不可靠控件的视觉状态（如自定义样式开关）\nfrom autocar import AT\nat = AT()\ncar = at.connect_device()\n\nICON = ('com.example:id/wifi_icon', 'id')\ncar.assert_image(ICON, baseline_img='page_objects/sources/img/wifi_on.png',\n    threshold=0.85, msg='Wi-Fi 图标应为已连接状态')\n# 无稳定 locator 时按屏幕区域比对（坐标与 assert_ocr 相同）\ncar.assert_image(\n    baseline_img='page_objects/sources/img/wallpaper_preview.png',\n    region=(0, 220, 2560, 850),\n)",
  "caller": "car.assert_image",
  "contract": {
    "status": "metadata_only",
    "scope": "registered_callable",
    "issues": [],
    "parameters": [
      {
        "name": "locator",
        "kind": "POSITIONAL_OR_KEYWORD",
        "required": false,
        "default": "None"
      },
      {
        "name": "baseline_img",
        "kind": "POSITIONAL_OR_KEYWORD",
        "required": false,
        "default": "''"
      },
      {
        "name": "by",
        "kind": "POSITIONAL_OR_KEYWORD",
        "required": false,
        "default": "'text'"
      },
      {
        "name": "threshold",
        "kind": "POSITIONAL_OR_KEYWORD",
